-- Phase 2 demo data for "Demo · Customer Portal": due dates, a backlog (epics/stories/tasks) and three sprints
-- (closed -> active with carry-over -> planned), so the workspace reads like a team mid-delivery.
-- Idempotent: fixed de300000-…-9000-… ids guard every insert; due dates only fill empty columns.
-- Apply:  npm run db:migrate -- database/demo/phase2_seed.sql   Remove: database/demo/phase2_remove.sql

-- ── A. Due dates over existing open demo bugs: a few overdue, some due today/tomorrow, the rest ahead ──
with pick as (select id, row_number() over (order by id) rn from bugflow.bugs where deleted_at is null and kind='bug' and due_on is null and project_id='de300000-0000-4000-8000-000000000001' and status not in ('RESOLVED','DUPLICATE','NOT_A_BUG','WONT_FIX'))
update bugflow.bugs b set due_on = current_date + (case p.rn % 7 when 0 then -6 when 1 then -2 when 2 then 0 when 3 then 1 when 4 then 3 when 5 then 8 else 13 end) from pick p where b.id=p.id and p.rn <= 14;

-- ── B. Backlog: epics first (parents), then stories/tasks that point at them ──
with created as (insert into bugflow.bugs (title,project_id,reporter_id,priority,severity,status,description,expected,actual,kind,estimate,ready,backlog_rank,created_at,updated_at) select 'Checkout revamp','de300000-0000-4000-8000-000000000001','de300000-0000-4000-8000-100000000008','P2','High','VALIDATING','One-page checkout, saved cards and guest flow — the Q4 conversion push.','','','epic',null,false,'c',now()-interval '18 days',now()-interval '2 days' where not exists (select 1 from bugflow.bug_details where request_id='de300000-0000-4000-9000-200000000001') returning id), details as (insert into bugflow.bug_details (bug_id,request_id,module_name,evidence_urls) select id,'de300000-0000-4000-9000-200000000001','Checkout','[]'::jsonb from created) insert into bugflow.status_history (id,bug_id,actor_id,new_status) select gen_random_uuid(),id,'de300000-0000-4000-8000-100000000008','NEW' from created;
with created as (insert into bugflow.bugs (title,project_id,reporter_id,priority,severity,status,description,expected,actual,kind,estimate,ready,backlog_rank,created_at,updated_at) select 'Mobile app polish','de300000-0000-4000-8000-000000000001','de300000-0000-4000-8000-100000000008','P3','Medium','VALIDATING','Round off the rough edges testers keep hitting on phones.','','','epic',null,false,'r',now()-interval '12 days',now()-interval '3 days' where not exists (select 1 from bugflow.bug_details where request_id='de300000-0000-4000-9000-200000000002') returning id), details as (insert into bugflow.bug_details (bug_id,request_id,module_name,evidence_urls) select id,'de300000-0000-4000-9000-200000000002','Mobile','[]'::jsonb from created) insert into bugflow.status_history (id,bug_id,actor_id,new_status) select gen_random_uuid(),id,'de300000-0000-4000-8000-100000000008','NEW' from created;
with created as (insert into bugflow.bugs (title,project_id,reporter_id,assignee_id,priority,severity,status,description,expected,actual,kind,parent_id,estimate,ready,backlog_rank,due_on,created_at,updated_at) select 'One-page checkout flow','de300000-0000-4000-8000-000000000001','de300000-0000-4000-8000-100000000008','de300000-0000-4000-8000-100000000004','P2','High','IN_PROGRESS','Collapse the 4-step checkout into one page with inline validation.','Single page, no reloads, same conversion events.','','story',(select bug_id from bugflow.bug_details where request_id='de300000-0000-4000-9000-200000000001'),8,true,'f',current_date+4,now()-interval '16 days',now()-interval '1 day' where not exists (select 1 from bugflow.bug_details where request_id='de300000-0000-4000-9000-200000000003') returning id), details as (insert into bugflow.bug_details (bug_id,request_id,module_name,evidence_urls) select id,'de300000-0000-4000-9000-200000000003','Checkout','[]'::jsonb from created) insert into bugflow.status_history (id,bug_id,actor_id,new_status) select gen_random_uuid(),id,'de300000-0000-4000-8000-100000000008','NEW' from created;
