-- ── C. Sprints: 14 closed, 15 active (one per project), 16 planned ──
insert into bugflow.sprints (id,project_id,name,goal,starts_on,ends_on,state,created_by,started_at,closed_at,created_at) select 'de300000-0000-4000-9000-100000000001','de300000-0000-4000-8000-000000000001','Sprint 14 — Checkout hardening','Clear the payment-blocking bugs before the saved-cards launch.',current_date-21,current_date-8,'closed','de300000-0000-4000-8000-100000000008',now()-interval '21 days',now()-interval '7 days',now()-interval '25 days' where not exists (select 1 from bugflow.sprints where id='de300000-0000-4000-9000-100000000001');
insert into bugflow.sprints (id,project_id,name,goal,starts_on,ends_on,state,created_by,started_at,created_at) select 'de300000-0000-4000-9000-100000000002','de300000-0000-4000-8000-000000000001','Sprint 15 — Mobile polish','Ship the one-page checkout and the top mobile annoyances.',current_date-4,current_date+10,'active','de300000-0000-4000-8000-100000000008',now()-interval '4 days',now()-interval '6 days' where not exists (select 1 from bugflow.sprints where project_id='de300000-0000-4000-8000-000000000001' and state='active') and not exists (select 1 from bugflow.sprints where id='de300000-0000-4000-9000-100000000002');
insert into bugflow.sprints (id,project_id,name,goal,starts_on,ends_on,state,created_by,created_at) select 'de300000-0000-4000-9000-100000000003','de300000-0000-4000-8000-000000000001','Sprint 16 — Reporting','Exports, team reports and the feedback loop.',current_date+11,current_date+25,'planned','de300000-0000-4000-8000-100000000008',now()-interval '2 days' where not exists (select 1 from bugflow.sprints where id='de300000-0000-4000-9000-100000000003');

-- Sprint 14 (closed): two bugs that got fixed and two that did not finish.
insert into bugflow.sprint_items (sprint_id,bug_id,added_at,added_by) select 'de300000-0000-4000-9000-100000000001',id,now()-interval '22 days','de300000-0000-4000-8000-100000000008' from (select id from bugflow.bugs where project_id='de300000-0000-4000-8000-000000000001' and deleted_at is null and kind='bug' and status='RESOLVED' order by id limit 2) r on conflict do nothing;
insert into bugflow.sprint_items (sprint_id,bug_id,added_at,added_by) select 'de300000-0000-4000-9000-100000000001',id,now()-interval '22 days','de300000-0000-4000-8000-100000000008' from (select id from bugflow.bugs where project_id='de300000-0000-4000-8000-000000000001' and deleted_at is null and kind='bug' and status not in ('RESOLVED','DUPLICATE','NOT_A_BUG','WONT_FIX') order by id limit 2) o on conflict do nothing;
-- Sprint 15 (active): the two unfinished Sprint-14 bugs carried over…
insert into bugflow.sprint_items (sprint_id,bug_id,added_at,added_by,carried_from_sprint_id) select 'de300000-0000-4000-9000-100000000002',si.bug_id,now()-interval '7 days','de300000-0000-4000-8000-100000000008','de300000-0000-4000-9000-100000000001' from bugflow.sprint_items si join bugflow.bugs b on b.id=si.bug_id where si.sprint_id='de300000-0000-4000-9000-100000000001' and b.status not in ('RESOLVED','DUPLICATE','NOT_A_BUG','WONT_FIX') on conflict do nothing;
-- …three more bugs committed at planning (guarded: the pick drifts between runs, so only on a sprint with no committed bugs yet)…
insert into bugflow.sprint_items (sprint_id,bug_id,added_at,added_by) select 'de300000-0000-4000-9000-100000000002',id,now()-interval '5 days','de300000-0000-4000-8000-100000000008' from (select id from bugflow.bugs where project_id='de300000-0000-4000-8000-000000000001' and deleted_at is null and kind='bug' and status not in ('RESOLVED','DUPLICATE','NOT_A_BUG','WONT_FIX') and id not in (select bug_id from bugflow.sprint_items) order by id limit 3) c where not exists (select 1 from bugflow.sprint_items si join bugflow.bugs b on b.id=si.bug_id where si.sprint_id='de300000-0000-4000-9000-100000000002' and si.carried_from_sprint_id is null and b.kind='bug' and si.added_at < now()-interval '2 days') on conflict do nothing;
-- …the two in-flight checkout stories committed too, and one bug pulled in after the start (added scope).
insert into bugflow.sprint_items (sprint_id,bug_id,added_at,added_by) select 'de300000-0000-4000-9000-100000000002',bug_id,now()-interval '5 days','de300000-0000-4000-8000-100000000008' from bugflow.bug_details where request_id in ('de300000-0000-4000-9000-200000000003','de300000-0000-4000-9000-200000000006') on conflict do nothing;
insert into bugflow.sprint_items (sprint_id,bug_id,added_at,added_by) select 'de300000-0000-4000-9000-100000000002',id,now()-interval '1 day','de300000-0000-4000-8000-100000000004' from (select id from bugflow.bugs where project_id='de300000-0000-4000-8000-000000000001' and deleted_at is null and kind='bug' and status not in ('RESOLVED','DUPLICATE','NOT_A_BUG','WONT_FIX') and id not in (select bug_id from bugflow.sprint_items) order by id limit 1) a where not exists (select 1 from bugflow.sprint_items si join bugflow.bugs b on b.id=si.bug_id where si.sprint_id='de300000-0000-4000-9000-100000000002' and si.carried_from_sprint_id is null and b.kind='bug' and si.added_at > now()-interval '2 days') on conflict do nothing;
-- Sprint 16 (planned): the groomed backlog stories wait here.
insert into bugflow.sprint_items (sprint_id,bug_id,added_at,added_by) select 'de300000-0000-4000-9000-100000000003',bug_id,now()-interval '2 days','de300000-0000-4000-8000-100000000008' from bugflow.bug_details where request_id in ('de300000-0000-4000-9000-200000000005','de300000-0000-4000-9000-200000000008') on conflict do nothing;

