insert into bugflow.activity (id,actor_id,action,detail,created_at) select 'de300000-0000-4000-9000-300000000002','de300000-0000-4000-8000-100000000008','sprint.closed','{"sprint":"de300000-0000-4000-9000-100000000001","carriedTo":"de300000-0000-4000-9000-100000000002"}'::jsonb,now()-interval '7 days' where not exists (select 1 from bugflow.activity where id='de300000-0000-4000-9000-300000000002');
insert into bugflow.activity (id,actor_id,action,detail,created_at) select 'de300000-0000-4000-9000-300000000003','de300000-0000-4000-8000-100000000008','sprint.started','{"sprint":"de300000-0000-4000-9000-100000000002"}'::jsonb,now()-interval '4 days' where not exists (select 1 from bugflow.activity where id='de300000-0000-4000-9000-300000000003');
